"""Independently audit the fixed resolver probe from raw files after completion.

Uses the earlier independent stdlib raw-owner checker, never the diagnostic
driver/analyzer or their derived observations. No JVM or subprocess is started.
No performance estimate, miss-rate estimate, or primary-study rescue is made.
"""
import argparse
import hashlib
import importlib.util
import json
from pathlib import Path
import re


HERE = Path(__file__).resolve().parent
RAW_HELPER = HERE / 'check-discovery-raw.py'
SPEC = importlib.util.spec_from_file_location('independent_raw_publication_records', RAW_HELPER)
raw = importlib.util.module_from_spec(SPEC)
SPEC.loader.exec_module(raw)
require, digest = raw.require, raw.digest
PROTOCOL_SHA = '0ba7dd6c7bce031e8c7495e6be958c13444a670ada1b966dde2fdfcb1f54ac5d'
MATERIALIZER_SHA = '95660f4dab2bd6d4ff947ee3f01ed3c61e6d00ace24722c27e8ff86aa782e317'
ORDER = ['all', 'omit', 'omit', 'all']
NAMES = ['s', 'a', 'l0', 'l1', 'r0', 'r1']
MASKS = {'all': '', 'omit': 'l0,l1'}
QUERY_LIMIT, GLOBAL_LIMIT = 536_870_912, 1_073_741_824
BASE_JVM = ['-Xms1024m', '-Xmx1024m', '-XX:+UseG1GC', '-Drdf4j.lmdb.hotCounters=true']
TERMINAL_MISSES = raw.FACTOR_OUTCOMES[:-1]
IDENTITY = ('type', 'target', 'name', 'canonical', 'definiteSlot', 'cacheBank')
SOURCES = {}


def pin(path):
    path = Path(path)
    result = digest(path)
    require(str(path) not in SOURCES or SOURCES[str(path)] == result, 'Input changed during audit: ' + str(path))
    SOURCES[str(path)] = result
    return result


def read_json(path):
    pin(path)
    return json.loads(Path(path).read_text())


def read_jsonl(path):
    pin(path)
    return [json.loads(line) for line in Path(path).read_text().splitlines()]


def verify_runtime(plan):
    runtime_path = Path(plan['runtime'])
    require(pin(runtime_path) == plan['runtimeSha256'], 'Runtime descriptor changed')
    runtime = read_json(runtime_path)
    require(runtime['diagnosticOnly'] and runtime['maskGuardPresent']
        and runtime['extraWeakDereferences'] == 0, 'Unexpected diagnostic runtime')
    require(runtime['sourceIdentity'] == plan['sourceIdentity'], 'Source identity changed')
    for name in ('baseRuntimeDescriptor', 'sourceGenerationFile', 'classpathFile', 'classpathManifestFile'):
        suffix = name + 'Sha256' if name + 'Sha256' in runtime else name[:-4] + 'Sha256'
        require(pin(runtime[name]) == runtime[suffix], 'Runtime support file changed: ' + name)
    entries = Path(runtime['classpathFile']).read_text().strip().split(':')
    require(len(entries) == len(runtime['manifest']) == 130, 'Expected exact 130-entry runtime')
    require(read_json(runtime['classpathManifestFile']) == runtime['manifest'], 'Manifest copies disagree')
    actual = []
    for entry in entries:
        path = Path(entry).resolve(strict=True)
        require(not path.is_symlink(), 'Classpath symlink is not frozen')
        if path.is_dir():
            files = []
            for item in sorted(path.rglob('*')):
                require(not item.is_symlink(), 'Runtime tree symlink is not frozen')
                if item.is_file():
                    files.append(item)
            h = hashlib.sha256()
            for item in files:
                h.update(item.relative_to(path).as_posix().encode() + b'\0')
                h.update(bytes.fromhex(digest(item)))
            actual.append({'path': str(path), 'kind': 'tree', 'files': len(files), 'sha256': h.hexdigest()})
        else:
            actual.append({'path': str(path), 'kind': 'file', 'sha256': digest(path)})
    require(actual == runtime['manifest'], 'Actual runtime bytes differ from the frozen manifest')
    generation = read_json(runtime['sourceGenerationFile'])
    source_root = runtime_path.parent
    package = Path('org/eclipse/rdf4j/sail/lmdb/evaluation')
    require(pin(source_root / 'src' / package / 'NativeResultMaterializer.java')
        == generation['generatedSourceSha256'] == MATERIALIZER_SHA, 'Generated materializer changed')
    require(pin(source_root / 'src' / package / 'PublicationDiagnostics.java')
        == generation['helperSha256'], 'Generated helper changed')
    require(pin(source_root / 'preimage' / package / 'NativeResultMaterializer.java')
        == generation['sourceSha256'], 'Materializer preimage changed')
    return ':'.join(entries), actual


def raw_targets(owner_file):
    """Read just the header/target prefix; the raw-owner checker audits all pages."""
    result = []
    with Path(owner_file).open() as stream:
        header = json.loads(next(stream))
        require(header['type'] == 'owner', 'Missing owner header')
        for line in stream:
            record = json.loads(line)
            if record['type'] == 'page':
                break
            require(record['type'] == 'target', 'Unexpected owner-prefix record')
            result.append(record)
    require(len(result) == 6, 'Expected six target records before pages')
    return result


def references(plan, diagnostic):
    result = {}
    for arm, suite_name in [('all', 'overlay-all512'), ('omit', 'overlay-shared-omit512')]:
        suite = diagnostic / 'suites' / suite_name
        suite_plan = read_json(suite / 'protocol.json')
        require(suite_plan['sourceIdentity'] == plan['sourceIdentity'], 'Reference source identity differs')
        require(suite_plan['mask'] == MASKS[arm] and suite_plan['queryLimitBytes'] == QUERY_LIMIT,
            'Reference arm/limit differs')
        fixture = raw.inspect_fixture(suite, 'shared-tail', suite_plan, SOURCES)
        queries = fixture['queries']
        require(len(queries) == 4 and all(q['resolverCalls'] == 32_833 for q in queries),
            'Reference raw resolver count differs')
        require(all(bank['totals']['rememberCall'] == sum(bank['totals'][key] for key in TERMINAL_MISSES)
            for query in queries for bank in query['banks'].values()), 'Reference terminal-factor partition differs')
        require(all(q['banks'] == queries[0]['banks'] for q in queries), 'Reference raw target counters differ')
        identities = [{key: target[key] for key in IDENTITY}
            for target in raw_targets(suite / 'runs/shared-tail/page-records/owner-1.jsonl')]
        for path, expected_sha in plan['references'][arm]['files'].items():
            require(pin(path) == expected_sha, 'Frozen comparison reference changed')
        # Claimed targets are checked only after the raw records were reconciled.
        for index, claimed in enumerate(plan['references'][arm]['targets']):
            bank = queries[0]['banks'][NAMES[index]]
            require({key: claimed[key] for key in raw.COUNTERS} == dict(bank['totals']),
                'Frozen reference counters disagree with independently read raw records')
            require({key: claimed[key] for key in IDENTITY} == identities[index], 'Reference target identity changed')
            require(all(claimed[key] == bank[key] for key in ('finalPages', 'finalPageBytes', 'finalOccupiedCells')),
                'Reference final page counts differ')
        result[arm] = {'suite': str(suite), 'queryCount': 4, 'query': queries[0], 'identities': identities}
    return result


def command_for(probe, index, arm, plan, cp):
    target = probe / 'runs' / f'{index:02d}-{arm}'
    gc_log = target / 'gc.log'
    jvm = BASE_JVM + [
        '-Drdf4j.lmdb.publicationDiagnostic.output=' + str(target / 'page-records'),
        '-Drdf4j.lmdb.queryMemory.perQueryMaxBytes=' + str(QUERY_LIMIT),
        '-Drdf4j.lmdb.resultCoordinateTransport=dense',
        '-Drdf4j.lmdb.resultCoordinates.experiment.omitFactorTargets=' + MASKS[arm],
        '-Xlog:gc*,gc+ref=debug:file=' + str(gc_log) + ':time,uptime,level,tags:filecount=0']
    label = f'resolver-variation-{index:02d}-{arm}'
    argv = [plan['java'], *jvm, '-cp', cp,
        'org.eclipse.rdf4j.sail.lmdb.evaluation.RootQualifiedSharedSelectionLauncher',
        '--arm=' + label, '--source=' + plan['sourceIdentity'],
        '--roots=64', '--left=128', '--right=128', '--tuple-width=2', '--warmup=8', '--iterations=5',
        '--consumption=full', '--store=' + str(target / 'store'), '--output=' + str(target / 'samples.jsonl')]
    return {'index': index, 'arm': arm, 'mask': MASKS[arm], 'runId': target.name, 'harnessArm': label,
        'directory': str(target), 'gcLog': str(gc_log), 'argv': argv, 'jvmArguments': jvm,
        'cwd': str(HERE.parents[2])}


def check_run(probe, entry, plan, reference):
    folder = Path(entry['directory'])
    command = read_json(folder / 'command.json')
    require({key: command[key] for key in entry} == entry, 'Actual recorded command differs')
    require(command['protocolSha256'] == PROTOCOL_SHA and command['runtimeSha256'] == plan['runtimeSha256'],
        'Command identity differs')
    process = read_json(folder / 'process-result.json')
    require(process['exitCode'] == 0 and not process['timedOut'], 'Probe JVM did not exit successfully')
    require(command['startedEpochNs'] < process['finishedEpochNs'], 'Invalid process interval')
    pin(folder / 'console.log')
    records = read_jsonl(folder / 'samples.jsonl')
    require(len(records) == 14 and records[0]['type'] == 'metadata', 'Expected metadata plus 13 queries')
    metadata, samples = records[0], records[1:]
    expected = {**plan['fixture']['metadata'], 'source': plan['sourceIdentity'], 'arm': entry['harnessArm'],
        'jvmArguments': entry['jvmArguments'], 'consumption': 'full', 'nativeEvaluation': True,
        'directAdjacency': True, 'directAdjacencyMode': 'PREFER', 'valueOverlay': False, 'forceSync': False,
        'globalLedgerLimitBytes': GLOBAL_LIMIT, 'perQueryLedgerLimitBytes': QUERY_LIMIT,
        'indexes': 'spoc,ospc,psoc,posc', 'warmup': 8, 'measurementsToRun': 5, 'projectedNames': NAMES,
        'javaVersion': '25.0.5+8-LTS', 'javaVendor': 'Eclipse Adoptium', 'maxHeapBytes': GLOBAL_LIMIT}
    for key, value in expected.items():
        require(metadata.get(key) == value, 'Metadata differs: ' + key)
    properties = dict(arg[2:].split('=', 1) for arg in entry['jvmArguments'] if arg.startswith('-Drdf4j.'))
    require(metadata['systemProperties'] == properties, 'Runtime properties differ')
    setup = metadata['adjacencySetup']
    require(setup['state'] == 'ACTIVE' and setup['currentRevisionReady'], 'Adjacency setup invalid')
    expected_owners = [f'owner-{i}.jsonl' for i in range(1, 14)]
    require(sorted(path.name for path in (folder / 'page-records').iterdir()) == sorted(expected_owners),
        'Unexpected owner file set')
    queries = []
    for i, sample in enumerate(samples):
        require(sample['stage'] == ('warmup' if i < 8 else 'measurement') and sample['iteration'] == i - 8,
            'Query chronology differs')
        require(all(sample[key] for key in ('valid', 'complete', 'rowCountValid', 'checksumValid',
            'exactBagValid', 'partialMembershipValid')) and sample['rows'] == 1048576
            and sample['checksum'] == '8327963502356915200', 'Result oracle failed')
        require(sample['ledgerBeforeBytes'] == sample['ledgerAfterBytes'] == 0 and sample['ledgerReleased']
            and 0 <= sample['ledgerPeakBytes'] <= QUERY_LIMIT, 'Query ledger invalid')
        require(sample['autoRequested'] and sample['auto'] and sample['successfulSelections']
            and all('forced' not in route['mode'] for route in sample['successfulSelections']), 'Not normal AUTO')
        counters, adjacency = sample['counters'], sample['adjacency']
        require(counters['semanticNativeCompiles'] == counters['irOpened'] == 1
            and counters['irRows'] == 1048576 and counters['coordinateAdmissions']['opened'] == 1,
            'Native/coordinate execution route differs')
        if i >= 8:
            require(counters['compiledBinds'] == 1 and counters['interpretedBinds']
                == counters['aggregateCompiledBinds'] == counters['aggregateInterpretedBinds'] == 0,
                'Observed query is not compiled native IR')
        require(adjacency['stateBefore'] == adjacency['stateAfter'] == 'ACTIVE' and adjacency['lookupHits'] > 0
            and adjacency['currentRevisionBefore'] == adjacency['appliedRevisionBefore']
            == adjacency['currentRevisionAfter'] == adjacency['appliedRevisionAfter'] == setup['currentDataRevision'],
            'Adjacency revision/read route invalid')
        owner_file = folder / 'page-records' / expected_owners[i]
        owner = raw.owner_totals(owner_file, sample, NAMES, QUERY_LIMIT, SOURCES)
        require(owner['owner'] == i + 1, 'Raw owner/query association differs')
        target_records = raw_targets(owner_file)
        require([{key: target[key] for key in IDENTITY} for target in target_records] == reference['identities'],
            'Raw target identity differs')
        target_changes = {}
        for name, bank in owner['banks'].items():
            counts, prior = bank['totals'], reference['query']['banks'][name]
            require(counts['rememberCall'] == sum(counts[key] for key in TERMINAL_MISSES),
                'Per-target terminal-factor-miss/resolver reconciliation failed')
            if name in MASKS[entry['arm']].split(','):
                require(counts['publicationSkipped'] == counts['publicationCall']
                    and counts['pageAdmitted'] == counts['publicationWrite'] == bank['finalPages'] == 0,
                    'Selected mask behavior differs')
            else:
                require(counts['publicationSkipped'] == 0, 'Unexpected target omitted')
            changes = {key: counts[key] - prior['totals'][key] for key in raw.COUNTERS
                if counts[key] != prior['totals'][key]}
            changes.update({key: bank[key] - prior[key]
                for key in ('finalPages', 'finalPageBytes', 'finalOccupiedCells') if bank[key] != prior[key]})
            if changes:
                target_changes[name] = changes
        totals = owner['totals']
        terminal = {key: totals[key] for key in TERMINAL_MISSES}
        require(sum(terminal.values()) == owner['resolverCalls'], 'Final-factor miss partition differs from resolvers')
        queries.append({**owner, 'sourceIdentity': plan['sourceIdentity'],
            'generatedMaterializerSha256': MATERIALIZER_SHA, 'rawOwnerFile': str(owner_file),
            'rawOwnerSha256': SOURCES[str(owner_file)], 'rawSampleFile': str(folder / 'samples.jsonl'),
            'rawSampleRecordIndex': i + 1, 'counters': counters, 'successfulSelections': sample['successfulSelections'],
            'adjacency': adjacency, 'ordinaryPartition': {key: totals[key] for key in raw.ORDINARY_OUTCOMES},
            'terminalFactorMissPartition': terminal,
            'resolverDifferenceFromSameArmReference': owner['resolverCalls'] - reference['query']['resolverCalls'],
            'counterChangesFromSameArmReference': target_changes,
            'originalTimingEventCauseEstablished': False})
    audit = read_json(folder / 'root-host-audit.json')
    require(audit['harnessReturned'] and audit['harnessFailureClass'] is None
        and audit['semanticNativeCompilesTotal'] == 13 and audit['hostedGenericTotal'] == 0
        and audit['harnessMain'] == plan['fixture']['harnessMain']
        and audit['readPhase'] == plan['fixture']['rootReadPhase'], 'Root-host route audit invalid')
    gc_file = folder / 'gc.log'
    gc_sha = pin(gc_file)
    gc_text = gc_file.read_text()
    require(gc_text and 'Using G1' in gc_text and 'System.gc()' not in gc_text, 'GC log invalid/explicit GC observed')
    require([path.name for path in folder.glob('gc.log*')] == ['gc.log'], 'Unexpected rotated GC files')
    gc = {'path': str(gc_file), 'sha256': gc_sha, 'bytes': gc_file.stat().st_size,
        'g1Declared': True, 'explicitSystemGcTextObserved': False,
        'referenceProcessingPresent': any(re.search(r'\[gc,ref\s*\]', line) for line in gc_text.splitlines()),
        'individualQueryAlignmentAvailable': False, 'performanceInference': False}
    return {'runId': entry['runId'], 'arm': entry['arm'], 'queryCount': 13,
        'processInterval': {'startEpochNs': command['startedEpochNs'], 'endEpochNs': process['finishedEpochNs']},
        'rawMetadata': metadata, 'queries': queries, 'gcLog': gc}


def report(result):
    lines = ['# Independent audit of the fixed resolver probe', '',
        'All four scheduled ABBA JVMs and all 52 queries passed independent raw reconciliation. '
        'The primary timing study remains failed/incomplete; no timing or allocation ratios were calculated.', '',
        'The checker reads raw commands, process results, samples, owner/page records, root audits, and GC logs. '
        'It uses the earlier independent raw-owner checker, not the diagnostic driver or its derived analyses. '
        'The same-arm references are independently recomputed from all eight earlier raw queries.', '',
        '## Every observed query', '',
        '| Run | Stage | Iteration | Resolvers | Delta from same-arm reference | Ordinary weak | Factor weak | Ordinary witness | Factor witness | Page refusals |',
        '| --- | --- | ---: | ---: | ---: | ---: | ---: | ---: | ---: | ---: |']
    for run in result['runs']:
        for query in run['queries']:
            t = query['totals']
            cells = [run['runId'], query['stage'], query['iteration'], query['resolverCalls'],
                query['resolverDifferenceFromSameArmReference'], t['ordinaryWeakMiss'], t['factorWeakMiss'],
                t['ordinaryWitnessMiss'], t['factorWitnessMiss'], t['pageRefused']]
            lines.append('| ' + ' | '.join(map(str, cells)) + ' |')
    lines += ['', '## Interpretation and preservation', '',
        'Each query has a complete exclusive final-factor decomposition and per-target changes in the JSON receipt. '
        'The five terminal miss outcomes sum to resolver calls globally and to remember calls per target. '
        'Ordinary weak branches are reported separately: a factor hit can recover one, and ordinary/factor weak '
        'branches can occur in the same lookup. Their counts must not be added as additional resolver calls.', '',
        'All query results, AUTO/native routes, compiled observed-query tiers, current adjacency revisions, root-host audits, '
        'page grant/release identities, and zero query-ledger endpoints passed. The four process intervals are serial. '
        'Every frozen runtime entry and source/reference input was rehashed and preserved.', '',
        'GC/reference logs are JVM-wide and do not associate a GC event with a query or referent. '
        'Instrumentation changes allocation and close-time page reporting differently between the arms. '
        'This receipt therefore makes no latency, allocation, GC-cost, natural miss-rate, or arm-performance inference. '
        'New branch observations do not retrospectively identify the earlier timing event. '
        'The fixed four-JVM scope is complete without replacement or extension.', '']
    return '\n'.join(lines)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--probe', type=Path, required=True)
    parser.add_argument('--output', type=Path, required=True)
    parser.add_argument('--post-probe-slot-released', action='store_true')
    args = parser.parse_args()
    require(args.post_probe_slot_released, 'Coordinator must release the post-probe analysis slot first')
    pin(__file__)
    pin(RAW_HELPER)
    probe = args.probe.resolve(strict=True)
    require(pin(probe / 'protocol.json') == PROTOCOL_SHA, 'Not the reviewed frozen probe protocol')
    plan = read_json(probe / 'protocol.json')
    require(plan['order'] == ORDER and plan['masks'] == MASKS and plan['warmup'] == 8 and plan['iterations'] == 5
        and plan['expectedJvmCount'] == 4 and plan['expectedQueryCount'] == 52, 'Fixed scope differs')
    require(plan['diagnosticOnly'] and not plan['performanceInference'] and not plan['acceptedTimingComparison']
        and plan['resolverVariationAllowed'] and not plan['gcQueryAlignmentAvailable'], 'Inference contract differs')
    require(plan['queryLimitBytes'] == QUERY_LIMIT and plan['globalLimitBytes'] == GLOBAL_LIMIT
        and plan['transport'] == 'dense' and plan['consumption'] == 'full'
        and plan['generatedMaterializerSha256'] == MATERIALIZER_SHA and plan['baseJvmArguments'] == BASE_JVM,
        'Configuration differs')
    for path, expected_sha in plan['sources'].items():
        require(pin(path) == expected_sha, 'Frozen source changed: ' + path)
    cp, manifest = verify_runtime(plan)
    expected_commands = [command_for(probe, i, arm, plan, cp) for i, arm in enumerate(ORDER)]
    require(plan['commands'] == expected_commands, 'Frozen command array does not match independently reconstructed schedule')
    require(sorted(path.name for path in (probe / 'runs').iterdir()) == sorted(c['runId'] for c in expected_commands),
        'Raw run directory set differs from the fixed schedule')
    reference = references(plan, probe.parent.parent)
    runs = [check_run(probe, entry, plan, reference[entry['arm']]) for entry in expected_commands]
    for previous, following in zip(runs, runs[1:]):
        require(previous['processInterval']['endEpochNs'] <= following['processInterval']['startEpochNs'],
            'Probe process intervals overlap')
    # Verify all consumed/pinned files once more to detect in-audit changes.
    for path, expected_sha in SOURCES.items():
        require(digest(path) == expected_sha, 'Input changed during independent audit: ' + path)
    pin(__file__)
    pin(RAW_HELPER)
    result = {'format': 1, 'valid': True, 'diagnosticOnly': True, 'javaProcessesLaunched': 0,
        'independentImplementation': 'stdlib raw files plus prior independent raw-owner checker; no diagnostic driver/analyzer imports',
        'probe': str(probe), 'protocolSha256': PROTOCOL_SHA, 'sourceIdentity': plan['sourceIdentity'],
        'jvmCount': len(runs), 'queryCount': sum(r['queryCount'] for r in runs), 'warmupQueryCount': 32,
        'furtherObservedQueryCount': 20, 'referenceQueryCount': 8, 'runtimeManifest': manifest,
        'allFrozenInputsUnchanged': True, 'processIntervalsSerial': True, 'allQueryLedgerEndpointsZero': True,
        'allResultsRoutesAndRootAuditsValid': True, 'allPageGrantsReleased': True,
        'allTerminalMissResolverReconciliationsValid': True, 'references': reference, 'runs': runs,
        'sourceFiles': dict(sorted(SOURCES.items())), 'performanceInference': False,
        'acceptedTimingComparison': False, 'originalTimingEventCauseEstablished': False,
        'limits': 'Instrumented observations only. Ordinary and factor weak events can overlap. '
            'GC logs cannot align events to queries/referents. No natural miss-rate or performance inference; '
            'primary timing study remains failed/incomplete.'}
    args.output.mkdir(parents=True, exist_ok=False)
    with (args.output / 'independent-resolver-probe.json').open('x') as stream:
        json.dump(result, stream, indent=2, sort_keys=True)
        stream.write('\n')
    with (args.output / 'independent-resolver-probe.md').open('x') as stream:
        stream.write(report(result))
    print(json.dumps({'valid': True, 'jvms': len(runs), 'queries': result['queryCount'],
        'output': str(args.output), 'acceptedTimingComparison': False,
        'resolverSequences': {r['runId']: [q['resolverCalls'] for q in r['queries']] for r in runs}}))


if __name__ == '__main__':
    main()
